<section class="wise-card"><span class="writer-kicker">First option · hosted payment</span><h2>Pay through Wise</h2><p>Add your permanent Wise payment link. Visitors continue to Wise first, with bank-account details as a second option. Business open links default to USD; personal links use the options Wise provides.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_hosted"><input type="hidden" name="version" value="<?=(int)($record['version']??0)?>"><div class="wise-field"><label for="wise-hosted-link">Permanent Wise payment link</label><input id="wise-hosted-link" name="hosted_link" type="url" maxlength="500" placeholder="Paste your own permanent Wise payment link" value="<?=e($record['hosted_link']??'')?>"><small>In Wise, choose Payments → Payment links → Your open link, or share your personal Wisetag link. Do not use a temporary payment request.</small></div><label class="wise-check"><input type="checkbox" name="hosted_enabled" value="1" <?=!empty($record['hosted_enabled'])?'checked':''?>><span>Show Pay through Wise first</span></label><label class="wise-check"><input type="checkbox" name="hosted_confirm" value="1"><span>I checked that this permanent link belongs to my intended receiving account and approve publishing it.</span></label><button class="wbtn primary">Save Wise payment link</button></form><p>Opening Wise does not confirm a payment. No card details are collected here.</p></section>
<section class="wise-section"><div class="wise-section-heading"><div><h2>Your receiving accounts</h2><p>Copy the bank details exactly as Wise supplies them. Each currency has its own account and publishing control.</p></div><span class="wise-pill">No details published until approved</span></div>

<nav class="wise-currency-tabs" aria-label="Receiving currency"><?php foreach(['EUR'=>['€','Euro','SEPA'],'USD'=>['$','US dollar','ACH'],'GBP'=>['£','British pound','UK transfer']]as$c=>$label):?><a href="<?=url('/write/wise?tab=accounts&currency='.$c)?>" <?=$currency===$c?'aria-current="page"':''?>><b><?=e($label[0])?></b><span><strong><?=e($c)?> · <?=e($label[1])?></strong><small><?=e($label[2])?> · <?=!empty($record['accounts'][$c]['enabled'])?'Published':'Private'?></small></span></a><?php endforeach;?></nav>
<?php foreach([$currency]as$c):$savedRow=$record['accounts'][$c]??[];$row=($accountInput['currency']??'')===$c?$accountInput['row']:$savedRow;?><section class="wise-card wise-currency-panel" id="wise-currency-<?=e($c)?>" >
<form method="post" data-wise-account-form><?=csrf_field()?><input type="hidden" name="action" value="save_currency"><input type="hidden" name="currency" value="<?=e($c)?>"><input type="hidden" name="version" value="<?=(int)($record['version']??0)?>"><div class="wise-card-heading"><div><span class="writer-kicker"><?=e(wise_giving_rail($c))?></span><h3><?=e($c)?> account details</h3></div><span class="wise-pill <?=!empty($savedRow['enabled'])?'is-ready':''?>"><?=!empty($savedRow['enabled'])?'Published':'Private draft'?></span></div>
<div class="wise-field-grid"><?php foreach(wise_giving_fields($c)as$key=>$label):$wide=in_array($key,['holder','bank_address','iban'],true);?><div class="wise-field <?=$wide?'wise-wide':''?>"><label for="wise-<?=e($c.'-'.$key)?>"><?=e($label)?><?php if($c==='GBP'&&in_array($key,['iban','bic'],true)):?><small>Optional · Wise-issued international details</small><?php endif;?></label>
<?php if($key==='bank_address'):?><textarea id="wise-<?=e($c.'-'.$key)?>" name="accounts[<?=e($c)?>][<?=e($key)?>]" rows="3" maxlength="500" autocomplete="off" placeholder="Bank address exactly as shown in Wise"><?=e($row[$key]??'')?></textarea><small>Use the bank’s address, rather than your home address.</small>
<?php elseif($key==='account_type'):?><select id="wise-<?=e($c.'-'.$key)?>" name="accounts[<?=e($c)?>][<?=e($key)?>]"><option value="">Choose as shown in Wise</option><option value="checking" <?=($row[$key]??'')==='checking'?'selected':''?>>Checking</option><option value="savings" <?=($row[$key]??'')==='savings'?'selected':''?>>Savings</option></select>
<?php else:?><input id="wise-<?=e($c.'-'.$key)?>" name="accounts[<?=e($c)?>][<?=e($key)?>]" maxlength="180" value="<?=e($row[$key]??'')?>" autocomplete="off" spellcheck="false"><?php endif;?></div><?php endforeach;?></div>
<p class="wise-callout"><?php if($c==='GBP'):?>Use account number and sort code for local UK transfers. If Wise supplies an IBAN, add it separately with its BIC; follow the instructions for that receiving route.<?php elseif($c==='USD'):?>Use the ACH routing number from Wise. A wire routing number is a different receiving route.<?php else:?>Use your EUR IBAN and BIC for SEPA transfers. The bank name and address should match the Wise receiving instructions.<?php endif;?></p>
<label class="wise-toggle"><input type="checkbox" name="accounts[<?=e($c)?>][enabled]" value="1" <?=!empty($row['enabled'])?'checked':''?>><span><strong>Show these <?=e($c)?> details on the giving page</strong><small>Leave off to keep this account private while you prepare it.</small></span></label><div class="wise-save-bar"><label class="wise-check"><input type="checkbox" name="confirm_public" value="1"><span>I checked these <?=e($c)?> details against Wise and approve publishing them if enabled.</span></label><div class="wise-save-actions"><button class="wbtn primary">Save <?=e($c)?> account</button><span data-wise-save-state role="status"><?php if(!empty($record['account_saved'][$c])):?>Last saved <?=e((new DateTimeImmutable('@'.$record['account_saved'][$c]))->setTimezone(comm_zone('Africa/Nairobi'))->format('j M Y · H:i'))?> EAT<?php else:?>Private until you save and approve publication<?php endif;?></span></div><p>Only this <?=e($c)?> account is saved. Your other currency accounts stay as saved.</p></div></form></section><?php endforeach;?></section>
